{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Odanacatib, the highest-transfer analogue sharing the methylsulfonyl-phenyl motif, had absolute oral bioavailability of 70% at 10 mg and 30% at 50 mg in humans, both above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pradigastat, a high-transfer biaryl analogue, was completely bioavailable after oral dosing in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Estazolam, a chloro-containing heteroaromatic analogue, showed 87% oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir, containing a methylated heteroaromatic ring and polar sulfonamide/sulfone-like group, showed 75% bioavailability after a single oral dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Iclepertin, a sulfone-containing clinical compound, had absolute oral bioavailability of 71.6% in humans under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Triazolam, a structurally related heteroaromatic chloro compound, had approximately 50% oral bioavailability in humans, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Even the lowest retrieved value, a predicted human oral bioavailability of 23% for compound 26, remains above the 20% threshold and is directionally supportive.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer analogues (assay-transfer scores ~0.987-0.989) show absolute oral bioavailability values above 20%, mostly 40-90%, and the query shares key structural features such as the methylsulfonyl-phenyl group and heteroaromatic chloroaryl system. No retrieved evidence supports low bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule itself.",
    "Some analogues show dose-dependent or solubility-limited absorption (e.g., odanacatib 30% at 50 mg), so the query's F could be lower at high doses, but still above the 20% threshold.",
    "The 23% value for compound 26 is a prediction from allometric scaling rather than an experimental measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

